const COMMON=[
 [/\bik heb (gegaan|gekomen|geweest|opgestaan|aangekomen|vertrokken|verhuisd)\b/i,Q("gaan, komen, zijn, opstaan, verhuizen → з «zijn»: ik ben gegaan.","gaan, komen, zijn, opstaan, verhuizen take «zijn»: ik ben gegaan.","gaan, komen, zijn, opstaan, verhuizen se construisent avec « zijn » : ik ben gegaan.","gaan وkomen وzijn وopstaan وverhuizen تأتي مع «zijn»: ik ben gegaan.")],
 [/\bik ben (gewerkt|gekocht|gegeten|gemaakt|gedaan|gelogeerd)\b/i,Q("werken, kopen, eten, maken, doen → з «hebben»: ik heb gewerkt.","werken, kopen, eten, maken, doen take «hebben»: ik heb gewerkt.","werken, kopen, eten, maken, doen se construisent avec « hebben » : ik heb gewerkt.","werken وkopen وeten وmaken وdoen تأتي مع «hebben»: ik heb gewerkt.")],
 [/\bomdat (ik|hij|zij|ze|we|wij|mijn \w+) (ben|is|zijn) \w+\s*([.,!?]|$)|\bomdat (ik|hij|zij|ze|we|wij|mijn \w+) (heb|heeft|hebben) (?!ge)\w+(?: \w+)?\s*([.,!?]|$)/im,Q("Після omdat дієслово йде в кінець: «omdat ik ziek ben».","After omdat the verb goes to the end: «omdat ik ziek ben».","Après omdat, le verbe va à la fin : « omdat ik ziek ben ».","بعد omdat يأتي الفعل في النهاية: «omdat ik ziek ben».")],
 [/\b\w+er als\b/i,Q("Після -er пишемо «dan»: groter dan.","After -er write «dan»: groter dan.","Après -er, on écrit « dan » : groter dan.","بعد -er نكتب «dan»: groter dan.")],
 [/\bgeop\w+|\bgein\w+|\bgeaan\w+/i,Q("Дієслова, що розділяються: op + ge + staan → opgestaan, in + ge + vuld → ingevuld.","Separable verbs: opgestaan, ingevuld, aangekomen.","Verbes séparables : opgestaan, ingevuld, aangekomen.","الأفعال المنفصلة: opgestaan، ingevuld، aangekomen.")],
 [/\bbedenkt\b/i,Q("«Bedenkt» → правильно «Bedankt» (дякую).","«Bedenkt» → write «Bedankt» (thanks).","« Bedenkt » → écris « Bedankt » (merci).","«Bedenkt» ← اكتب «Bedankt» (شكراً).")]
];
const SPREKEN=[
 {id:"verleden",t:Q("Що я робив (perfectum)","What I did (perfect tense)","Ce que j’ai fait (passé composé)","ما فعلته (الماضي التام)"),qa:[["Wat heb je gisteren gedaan?","Gisteren heb ik gewerkt en daarna heb ik gekookt.","Що ти робив учора?","Учора я працював, а потім готував."],["Hoe laat ben je vanmorgen opgestaan?","Ik ben om zeven uur opgestaan.","О котрій ти встав сьогодні вранці?","Я встав о сьомій."],["Waar ben je vorig weekend geweest?","Vorig weekend ben ik naar Antwerpen geweest.","Де ти був минулих вихідних?","Минулих вихідних я їздив до Антверпена."],["Wat heb je daar gedaan?","We hebben de zoo bezocht.","Що ти там робив?","Ми відвідали зоопарк."],["Waar heb je vroeger gewoond?","Vroeger heb ik in Kyiv gewoond.","Де ти жив раніше?","Раніше я жив у Києві."],["Wat was je beroep in Oekraïne?","In Oekraïne was ik verpleegster.","Ким ти працював в Україні?","В Україні я була медсестрою."]]},
 {id:"werk",t:Q("Робота й навчання","Work and learning","Travail et formation","العمل والتعلّم"),qa:[["Werk je nu?","Ja, ik werk in een supermarkt.","Ти зараз працюєш?","Так, я працюю в супермаркеті."],["Welk werk wil je doen?","Ik wil in de zorg werken.","Яку роботу ти хочеш?","Я хочу працювати в догляді за людьми."],["Hoeveel uur per week werk je?","Ik werk twintig uur per week.","Скільки годин на тиждень ти працюєш?","Я працюю двадцять годин на тиждень."],["Waarom leer je Nederlands?","Ik leer Nederlands omdat ik hier wil werken.","Чому ти вчиш нідерландську?","Я вчу нідерландську, тому що хочу тут працювати."],["Kun je in het weekend werken?","Ja, op zaterdag kan ik werken.","Ти можеш працювати на вихідних?","Так, у суботу я можу працювати."],["Wanneer kan je beginnen?","Ik kan volgende maand beginnen.","Коли ти можеш почати?","Я можу почати наступного місяця."]]},
 {id:"zorg",t:Q("Здоров’я: лікар і аптека","Health: doctor and pharmacy","Santé : médecin et pharmacie","الصحة: الطبيب والصيدلية"),qa:[["Wat scheelt er?","Ik heb keelpijn en ik hoest veel.","Що вас турбує?","У мене болить горло, і я сильно кашляю."],["Sinds wanneer?","Sinds gisteren.","Відколи?","З учора."],["Hebt u koorts?","Ja, ik heb 38 graden koorts.","У вас є температура?","Так, у мене 38."],["Wat vraag je in de apotheek?","Hebt u iets tegen hoest?","Що ти попросиш в аптеці?","У вас є щось від кашлю?"],["Wat doe je op zondag als je medicijnen nodig hebt?","Ik zoek de wachtapotheek.","Що ти робиш у неділю, якщо потрібні ліки?","Я шукаю чергову аптеку."],["Wat heb je nodig voor je werk als je ziek bent?","Ik heb een ziektebriefje nodig.","Що тобі потрібно для роботи, коли ти хворієш?","Мені потрібна лікарняна довідка."]]},
 {id:"wonen",t:Q("Житло й сусіди","Home and neighbours","Logement et voisins","السكن والجيران"),qa:[["Waar woon je?","Ik woon in een appartement in Gent.","Де ти живеш?","Я живу в квартирі в Генті."],["Hoeveel kamers heeft je appartement?","Mijn appartement heeft twee slaapkamers.","Скільки кімнат у твоїй квартирі?","У моїй квартирі дві спальні."],["Wat is er kapot? Wat zeg je tegen de huisbaas?","De verwarming werkt niet. Wanneer kan de loodgieter komen?","Що зламалося? Що ти скажеш орендодавцю?","Опалення не працює. Коли може прийти сантехнік?"],["Ken je je buren?","Ja, mijn buren zijn heel vriendelijk.","Ти знаєш своїх сусідів?","Так, мої сусіди дуже привітні."],["Hoe stel je je voor aan een nieuwe buur?","Dag, ik ben Olena, uw nieuwe buurvrouw.","Як ти представишся новому сусідові?","Добрий день, я Олена, ваша нова сусідка."],["Wie doet bij jou thuis de afwas?","Bij ons doet mijn man de afwas.","Хто у вас удома миє посуд?","У нас посуд миє мій чоловік."]]},
 {id:"stad",t:Q("Місто й дорога","Town and directions","La ville et le chemin","المدينة والطريق"),qa:[["Hoe kom je naar de les?","Ik kom met de bus naar de les.","Як ти добираєшся на заняття?","Я приїжджаю на заняття автобусом."],["Waar is de apotheek?","De apotheek is op de hoek, naast de bank.","Де аптека?","Аптека на розі, поруч із банком."],["Hoe kom ik bij het station?","Ga rechtdoor en sla aan het kruispunt linksaf.","Як мені дійти до вокзалу?","Ідіть прямо й на перехресті поверніть ліворуч."],["Is het ver te voet?","Nee, het is tien minuten wandelen.","Це далеко пішки?","Ні, це десять хвилин пішки."],["Je trein heeft vertraging. Wat doe je?","Ik bel mijn werk en ik wacht op de volgende trein.","Твій поїзд запізнюється. Що ти робиш?","Я дзвоню на роботу й чекаю наступного поїзда."],["Waarom ga je naar het gemeentehuis?","Ik ga naar het gemeentehuis omdat ik een nieuwe identiteitskaart nodig heb.","Чому ти йдеш до будинку громади?","Я йду до будинку громади, тому що мені потрібна нова ID-картка."]]},
 {id:"plannen",t:Q("Вільний час і плани","Free time and plans","Loisirs et projets","وقت الفراغ والخطط"),qa:[["Wat doe je graag in je vrije tijd?","Ik zwem graag en ik lees veel.","Що ти любиш робити у вільний час?","Я люблю плавати й багато читаю."],["Wat vind je leuker: fietsen of wandelen?","Ik vind fietsen leuker dan wandelen.","Що тобі подобається більше: велосипед чи прогулянки?","Мені велосипед подобається більше, ніж прогулянки."],["Wat ga je dit weekend doen?","Dit weekend ga ik naar zee.","Що ти робитимеш на цих вихідних?","На цих вихідних я поїду на море."],["Wat zijn je plannen voor volgend jaar?","Volgend jaar wil ik werk zoeken.","Які твої плани на наступний рік?","Наступного року я хочу шукати роботу."],["Wat wil je eerst doen?","Eerst wil ik beter Nederlands spreken.","Що ти хочеш зробити спочатку?","Спочатку я хочу краще говорити нідерландською."],["Hoe voel je je vandaag? Waarom?","Ik ben tevreden, want ik heb veel geleerd.","Як ти почуваєшся сьогодні? Чому?","Я задоволений, бо багато вивчив."]]}
];
